package com.meddibuddy.security;
import io.jsonwebtoken.Jwts;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.util.Date;import java.time.Instant;import java.time.temporal.ChronoUnit;
@Component public class JwtService { private final SecretKey key; public JwtService(@Value("${app.jwt.secret}") String secret){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));} public String issue(String email,String role){Instant now=Instant.now();return Jwts.builder().subject(email).claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plus(12,ChronoUnit.HOURS))).signWith(key).compact();} public io.jsonwebtoken.Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
